        q("f13",YdsTopic.Completion,YdsDifficulty.Medium,"The results ____ by an independent panel before publication.","were reviewed","had reviewing","has review","were reviewing by","Past passive: were + V3.","review"),
        q("f14",YdsTopic.Completion,YdsDifficulty.Hard,"No sooner ____ the trial begun than the equipment failed.","had","was","did","has","No sooner had + özne + V3 than ... devrik geçmiş yapıdır.","had"),
        q("f15",YdsTopic.Completion,YdsDifficulty.Hard,"It is imperative that every participant ____ informed consent.","give","gives","gave","giving","Resmî İngilizcede imperative that + subject + base form.","give"),
