        q("s11",YdsTopic.Synonym,YdsDifficulty.Easy,"'Reduce' sözcüğünün en yakın anlamı hangisidir?","decrease","increase","expect","ignore","Reduce = azaltmak; decrease yakın anlamlıdır.","reduce"),
        q("s12",YdsTopic.Synonym,YdsDifficulty.Medium,"'The results were tentative.' cümlesinin en yakın anlamı hangisidir?","The findings were provisional.","The findings were final and absolute.","The findings were irrelevant.","The findings were secret.","Tentative = kesin olmayan/geçici; provisional yakın anlamlıdır.","tentative"),
        q("s13",YdsTopic.Synonym,YdsDifficulty.Medium,"'The method proved feasible.' yakın anlamı nedir?","The approach was practicable.","The approach was impossible.","The approach was unlawful.","The approach was never discussed.","Feasible = uygulanabilir, practicable = pratik olarak yapılabilir.","feasible"),
        q("s14",YdsTopic.Synonym,YdsDifficulty.Hard,"'The distinction is negligible.' en yakın anlamlı cümleyi seç.","The difference is too small to matter.","The difference is decisive.","There is no comparison.","The distinction is unknown to everyone.","Negligible = ihmal edilebilir kadar küçük.","negligible"),
        q("s15",YdsTopic.Synonym,YdsDifficulty.Hard,"'The conclusion is untenable.' yakın anlamı nedir?","The claim cannot be defended convincingly.","The claim is beyond any doubt.","The conclusion has been published.","The statement is easy to pronounce.","Untenable = savunulamaz, sürdürülemez.","untenable"),
